473	/** Monatliche CFADS und Schuldendienst aus den Zählerwerten der Anlage (fehlende Monate: Prognose, gekennzeichnet) */
474	async function monatsreihe(db, f) {
475	  const a = (db.anlagen?.anlagen || []).find((x) => x.id === f.bezugId);
476	  if (!a || !f.kreditvertrag) return [];
477	  const vertrag = (db.anlagen.vertraege || []).find((x) => x.anlageId === a.id);
478	  const mps = new Map((db.anlagen.messpunkte || []).map((m) => [m.id, m]));
479	  let zeilen = [];
480	  try {
481	    zeilen = await anlagenDemo.zaehlerMonatswerte(SYSTEM_LESER, a.id);
482	  } catch {
483	    zeilen = [];
484	  }
485	  const monate = new Map();
486	  for (const z of zeilen) {
487	    const mp = mps.get(z.messpunktId);
488	    const m = monate.get(z.monat) || { erzeugung: 0, einspeisung: 0 };
489	    if (mp?.art === "erzeugung" && mp.abrechnungsrelevant) m.erzeugung += Number(z.menge) || 0;
490	    if (mp?.art === "zweirichtung" && z.register === "2.8.0") m.einspeisung += Number(z.menge) || 0;
491	    monate.set(z.monat, m);
492	  }
493	  const e = f.eingaben;
494	  const kv = f.kreditvertrag;
495	  const plan = kreditPlan(kv);
496	  const start = kv.auszahlungAm || kv.unterzeichnetAm;
497	  const aktuell = new Date().toISOString().slice(0, 7);
498	  const reihe = [];
499	  for (const [monat, m] of [...monate.entries()].sort()) {
500	    if (monat >= aktuell) continue; // laufender Monat unvollständig
501	    const eigen = Math.max(0, m.erzeugung - m.einspeisung);
502	    const erloes = (eigen * (vertrag?.strompreisCt || e.preisCt)) / 100 + (Number(vertrag?.grundgebuehrMonat) || 0) + (m.einspeisung * (e.merchantCt || ERLOESE.merchantCt)) / 100;
503	    const kosten = (e.mwp * 1000 * e.opexKwp) / 12 + (e.pachtJahr || 0) / 12;
504	    const jahrIdx = Math.max(0, Math.floor((new Date(`${monat}-15`) - new Date(start)) / (365.25 * 86400e3)));
505	    const ds = monat < start.slice(0, 7) ? 0 : (plan.dienst[jahrIdx] || 0) / 12;
506	    reihe.push({ monat, erzeugung: m.erzeugung, einspeisung: m.einspeisung, erloes, kosten, cfads: erloes - kosten, schuldendienst: ds, quelle: "zaehler" });
507	  }
508	  return reihe;
509	}
