511	async function covenantFall(fallId, n = null) {
512	  const db = await lesenBereit();
513	  const f = fallLaden(db, fallId);
514	  if (!f.kreditvertrag) throw konflikt("Ohne Kreditvertrag gibt es keine Covenants.");
515	  if (f.bezugArt !== "anlage") throw konflikt("Covenant-Monitoring braucht eine verknüpfte Anlage (Messdaten).");
516	  const reihe = await monatsreihe(db, f);
517	  const kv = f.kreditvertrag;
518	  const plan = kreditPlan(kv);
519	  const start = new Date(kv.auszahlungAm || kv.unterzeichnetAm);
520	  const jahrIdx = Math.max(0, Math.floor((Date.now() - start) / (365.25 * 86400e3)));
521	  const restschuld = jahrIdx > 0 ? plan.rest[jahrIdx - 1] : kv.betrag;
522	  const planCfads = betriebsJahre(f.eingaben).slice(jahrIdx, kv.laufzeitJahre).map((j) => j.cfads90);
523	  const ergebnis = covenantPruefung({ monate: reihe, lockup: kv.dscrLockup, covenant: kv.dscrCovenant, llcrCovenant: kv.llcrCovenant, restschuld, planCfads, zins: kv.zinsPct / 100 });
524	  return aendern((d) => {
525	    const ff = fallLaden(d, fallId);
526	    const vorher = ff.covenant?.ampel?.id || null;
527	    ff.covenant = { ...ergebnis, monate: reihe.slice(-24), restschuld, geprueftAm: jetzt() };
528	    if (vorher !== ergebnis.ampel.id && ["gelb", "rot"].includes(ergebnis.ampel.id)) {
529	      for (const u of aktiveAdmins(d).filter((x) => darfLesen(x, "finanzierung"))) {
530	        benachrichtigen(d, u, { art: "finanzierung", titel: ergebnis.ampel.id === "rot" ? "Covenant: Lock-up bzw. Verletzung" : "Covenant-Frühwarnung", text: `${ff.titel}: ${ergebnis.ampel.grund}`, link: `/portal/admin/finanzierung/${ff.id}?tab=covenants`, objektArt: "finanzierung", objektId: ff.id });
531	      }
532	    }
533	    if (vorher !== ergebnis.ampel.id) verlauf(ff, n, d, `Covenant-Ampel: ${ergebnis.ampel.id} – ${ergebnis.ampel.grund}`);
534	    return ff.covenant;
535	  });
536	}
