export const HONORAR_ARTEN = { pauschal: "Pauschalhonorar", stunden: "Nach Aufwand (Stundensatz)" };
export const LIEFER_ARTEN = { entwurf: "Entwurf / Zwischenstand", endfassung: "Endfassung" };
