export const TERMIN_STATUS = { vorgeschlagen: { label: "Vorgeschlagen", ton: "info" }, bestaetigt: { label: "Bestätigt", ton: "ok" }, erledigt: { label: "Erledigt", ton: "neutral" }, abgesagt: { label: "Abgesagt", ton: "neutral" } };
