/** Zulässige Umsatzsteuersätze in % (DE 19/7, AT 20/13/10, CH 8,1/2,6; 0 = Reverse Charge bzw. Kleinunternehmer) */
export const UST_SAETZE = [0, 2.6, 7, 8.1, 10, 13, 19, 20];
