export const BEWERTUNG_KRITERIEN = { qualitaet: "Fachliche Qualität", termintreue: "Termintreue", kommunikation: "Kommunikation", preisLeistung: "Preis-Leistung" };
export const ZAHLUNGSZIEL_STANDARD = 30;

