  a11.verlauf.push({ am: vorTagen(6), text: "Term Sheet von der Bank eingereicht", fuerBank: true });
  const a12 = A(f1, b2, { status: "termsheet" });
  TS(a12, "backoffice", { betrag: f1.betragWunsch, laufzeitJahre: 18, zinsArt: "euribor6", referenzAnnahmePct: 2.7, margePct: 1.65, tilgungsprofil: "skulptiert", dscrSizing: 1.2, dscrCovenant: 1.05, dscrLockup: 1.1, llcrCovenant: 1.1, dsraMonate: 6, bearbeitun
  a12.verlauf.push({ am: vorTagen(4), text: "Term Sheet durch ÖkoInvest erfasst", fuerBank: true });
