  // ---------------------------------------------------------------- Fälle 2/3: Anlagen im Betrieb (Covenants)
  const anlagen = db.anlagen?.anlagen || [];
  // Agri-PV: hoch aufgeständert (Capex höher), Kredit knapp bemessen → mit der simulierten Minderleistung Frühwarnung bzw. Lock-up
