  st.s.rechteck(RAND, st.y + 5, 24, 2.2, F.ov500);
  st.y += 22;
};
const absatz = (t, { groesse = 9, farbe = F.ink700 } = {}) => {
  platz(24);
  st.y = st.s.absatz(RAND, st.y, t, { breite: B, groesse, farbe }) + groesse * 1.6;
};
const kacheln = (liste) => {
  platz(58);
  const n = liste.length;
  const b = (B - (n - 1) * 8) / n;
  liste.forEach(([label, wert], i) => {
    const x = RAND + i * (b + 8);
