      {text && <p className="mt-1.5 max-w-md text-[14.5px] leading-relaxed text-ink-600">{text}</p>}
      {aktion && <div className="mt-5">{aktion}</div>}
    </div>
  );
}

/** Schlüssel-Wert-Liste */
