                            <ArrowRight aria-hidden="true" className="hidden h-4 w-4 text-ink-400 transition-transform group-hover:translate-x-0.5 md:block" />
                          </span>
                        </Link>
                      </li>
                    ))}
                  </ul>
                </Karte>
              );
            })}
          </div>
          <div className="space-y-6">
